int main(){
double state=0.5,variance=1.0;
double transition=0.9,processVar=0.1,observed=1.2,measurementVar=0.2;
double predicted=transition*state;
double predictedVar=transition*transition*variance+processVar;
double gain=predictedVar/(predictedVar+measurementVar);
