#include <iostream>
#include <vector>
#include <cmath>
#include <iomanip>
using namespace std;

int main() {
    vector<int> observations={1,0,1,1,0,1};
    int successes=0;
    for(int value:observations)successes+=value;
    int n=int(observations.size());
    double probability=0.6;
    double bernoulliLogLikelihood=successes*log(probability)+(n-successes)*log(1-probability);
    double binomialLogProbability=lgamma(n+1)-lgamma(successes+1)-lgamma(n-successes+1)+bernoulliLogLikelihood;
    cout<<fixed<<setprecision(9)<<"Bernoulli likelihood "<<exp(bernoulliLogLikelihood)<<"\n";
    cout<<"Binomial count probability "<<exp(binomialLogProbability)<<"\n";
    return 0;
}
